/* @socom-skeleton body Normalize__6CPnt3DFv */
void CPnt3D::Normalize()
{
	f32 sqrMagnitude = sqrtf(z * z + x * x + y * y);

	if (sqrMagnitude != 0.0f)
	{
		sqrMagnitude = 1.0f / sqrMagnitude;
		x *= sqrMagnitude;
		y *= sqrMagnitude;
		z *= sqrMagnitude;
	}
}

/* @socom-skeleton body Normalize__6CPnt3DCFP6CPnt3D */
float CPnt3D::Normalize(CPnt3D *other) const
{
	f32 sqrMagnitude = sqrtf(z * z + x * x + y * y);

	if (sqrMagnitude != 0.0f)
	{
		sqrMagnitude = 1.0f / sqrMagnitude;
		other->x = x * sqrMagnitude;
		other->y = y * sqrMagnitude;
		other->z = z * sqrMagnitude;
	}
}

/* @socom-skeleton body Interp__6CPnt3DCFPC6CPnt3DfP6CPnt3D */
void CPnt3D::Interp(const CPnt3D *from, float step, CPnt3D *to) const
{
	if (step == 0.0f)
	{
		to = this;
	}
	else
	{
		f32 value = 1.0f - step;

		if (step == 1.0f)
		{
			to->x = from->x;
			to->y = from->y;
			to->z = from->z;
		}
		else
		{
			to->x = x * value;
			to->y = y * value;
			to->z = z * value;

			to->x += from->x * step;
			to->y += from->y * step;
			to->z += from->z * step;
		}
	}
}

